#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdlib>

int main() {
    int totalNumbers, budget;
    std::cin >> totalNumbers >> budget;
    std::vector<int> data(totalNumbers);
    int evenCount = 0, oddCount = 0;
    for (int i = 0; i < totalNumbers; i++) {
        std::cin >> data[i];
        if (data[i] % 2 == 0) {
            evenCount++;
        } else {
            oddCount++;
        }
    }
    if (evenCount != oddCount) {
        std::cout << 0 << std::endl;
    } else {
        std::vector<int> differences;
        int evenPairsCount = 0, oddPairsCount = 0;
        for (int i = 0; i < totalNumbers - 1; i++) {
            if (data[i] % 2 == 0) {
                evenPairsCount++;
            } else {
                oddPairsCount++;
            }
            if (evenPairsCount == oddPairsCount) {
                differences.push_back(std::abs(data[i + 1] - data[i]));
            }
        }
        std::sort(differences.begin(), differences.end());
        int currentSum = 0, selectedCount = 0;
        for (int diff : differences) {
            if (currentSum + diff <= budget) {
                currentSum += diff;
                selectedCount++;
            } else {
                break;
            }
        }
        std::cout << selectedCount << std::endl;
    }
    return 0;
}
